import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Vector2 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const { paper, accent, surface } = config.intent?.visualSpec?.colors || {};

  // --- Card dimensions (scene units) ---
  const cardWidth = 2.0;
  const cardHeight = cardWidth * (320 / 512); // maintain source rect aspect ratio
  const borderWidth = 0.03;

  // --- Background (accent edge on left) ---
  const bgGeom = new PlaneGeometry(cardWidth + borderWidth * 2, cardHeight + borderWidth * 2);
  const bgMat = new MeshBasicNodeMaterial({ color: accent || '#ff2a38' });
  const bgMesh = new Mesh(bgGeom, bgMat);
  group.add(bgMesh);

  // --- Front (paper) with texture ---
  const frontGeom = new PlaneGeometry(cardWidth, cardHeight);
  const frontMat = new MeshBasicNodeMaterial({
    color: paper || '#e8ecf2',
    transparent: false,
    side: ctx.THREE.DoubleSide // ensure visible
  });
  const frontMesh = new Mesh(frontGeom, frontMat);
  group.add(frontMesh);

  // --- Texture loading ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Atlas region: (0,0,512,320) – assume texture is the exact card, no offset
      tex.repeat.set(1, 1);
      tex.offset.set(0, 0);
      frontMat.map = tex;
      frontMat.needsUpdate = true;
    });
  }

  // --- Accent edge (thin line on left side) ---
  const edgeGeom = new PlaneGeometry(borderWidth, cardHeight);
  const edgeMat = new MeshBasicNodeMaterial({ color: accent || '#ff2a38', transparent: true, opacity: 1 });
  const edgeMesh = new Mesh(edgeGeom, edgeMat);
  edgeMesh.position.x = -cardWidth / 2 - borderWidth / 2;
  group.add(edgeMesh);

  // --- Store initial position for hover lift ---
  const originalY = group.position.y; // will be overridden by adapter, but stored for relative anim
  group.userData.originalY = 0; // we'll update in handler

  // --- GSAP timelines ---
  const hoverTimeline = gsap.timeline({ paused: true });
  const clickTimeline = gsap.timeline({ paused: true });

  // --- Handlers ---
  group.userData.handlers = {
    hover: {
      onEnter: () => {
        // Rise-in: y +0.15 scene units
        hoverTimeline.to(group.position, {
          y: originalY + 0.15,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: true
        });
        // Accent edge fade in (slightly more visible)
        gsap.to(edgeMat, { opacity: 1, duration: 0.2 });
      },
      onLeave: () => {
        hoverTimeline.reverse();
        gsap.to(edgeMat, { opacity: 0.7, duration: 0.2 });
      }
    },
    click: () => {
      // Press-down scale
      clickTimeline.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        onComplete: () => {
          clickTimeline.to(group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'power2.out'
          });
        }
      });
      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-pricing.select' });
    },
    focus: {
      onFocus: () => {
        // Accent edge visible
        gsap.to(edgeMat, { opacity: 1, duration: 0.2 });
      },
      onBlur: () => {
        gsap.to(edgeMat, { opacity: 0.7, duration: 0.2 });
      }
    }
  };

  // --- Cinematic primitive: parallax-scroll ---
  const scrollPrimitive = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
  const scrollCleanup = scrollPrimitive?.cleanup || (() => {});

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    hoverTimeline.kill();
    clickTimeline.kill();
    // Dispose geometries and materials
    bgGeom.dispose();
    bgMat.dispose();
    frontGeom.dispose();
    frontMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();
    // Primitive cleanup
    scrollCleanup();
  };

  return group;
}
